-- Sprint 82.5: real AI creative generation, private assets, draft-only governance.
alter table public.creative_assets add column if not exists storage_path text;
alter table public.creative_assets add column if not exists mime_type text check(mime_type in('image/png','image/jpeg'));
alter table public.creative_assets add column if not exists model text;
alter table public.creative_assets add column if not exists reasoning_summary text;
alter table public.creative_assets add column if not exists cache_key text;
alter table public.creative_campaigns drop constraint if exists creative_campaigns_selected_variation_check;
alter table public.creative_campaigns add constraint creative_campaigns_selected_variation_check check(selected_variation in('Version A','Version B','Version C','Version D'));
create unique index if not exists creative_asset_cache_idx on public.creative_assets(workspace_id,cache_key)where cache_key is not null;
create table if not exists public.creative_generation_jobs(
 id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,project_id uuid not null references public.inventory_projects(id),campaign_id uuid not null references public.creative_campaigns(id)on delete cascade,prompt text not null check(char_length(prompt)between 1 and 2000),format text not null,layout_style text not null check(layout_style in('Luxury','Modern','Minimal','Corporate','Festival','Offer','Investment','Premium','Dark','Light')),cache_key text not null,status text not null default'queued'check(status in('queued','processing','completed','failed')),progress integer not null default 0 check(progress between 0 and 100),attempts integer not null default 0,max_attempts integer not null default 3 check(max_attempts between 1 and 5),asset_id uuid references public.creative_assets(id),diagnostic text,claimed_at timestamptz,completed_at timestamptz,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index if not exists creative_jobs_queue_idx on public.creative_generation_jobs(status,created_at)where status in('queued','processing');
create index if not exists creative_jobs_tenant_idx on public.creative_generation_jobs(organization_id,workspace_id,created_at desc);
create table if not exists public.creative_editor_documents(
 asset_id uuid primary key references public.creative_assets(id)on delete cascade,organization_id uuid not null references public.organizations(id)on delete cascade,workspace_id uuid not null references public.workspaces(id)on delete cascade,width integer not null check(width between 320 and 4096),height integer not null check(height between 320 and 4096),elements jsonb not null default'[]',revision integer not null default 1,updated_by uuid not null references auth.users(id),updated_at timestamptz not null default now()
);
alter table public.creative_generation_jobs enable row level security;alter table public.creative_editor_documents enable row level security;
create policy "creative_jobs_read" on public.creative_generation_jobs for select to authenticated using(public.creative_studio_member(organization_id,workspace_id));
create policy "creative_editor_read" on public.creative_editor_documents for select to authenticated using(public.creative_studio_member(organization_id,workspace_id));
create policy "creative_editor_write" on public.creative_editor_documents for all to authenticated using(public.creative_studio_member(organization_id,workspace_id)and public.creative_studio_manage(workspace_id))with check(public.creative_studio_member(organization_id,workspace_id)and public.creative_studio_manage(workspace_id));
create or replace function public.enqueue_creative_generation(p_input jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare p public.inventory_projects%rowtype;c uuid;j uuid;cached uuid;begin select*into p from public.inventory_projects where id=(p_input->>'projectId')::uuid;if not found or not public.creative_studio_member(p.organization_id,p.workspace_id)or not public.creative_studio_manage(p.workspace_id)then raise exception'insufficient creative generation permission';end if;if char_length(trim(p_input->>'prompt'))not between 1 and 2000 then raise exception'invalid creative prompt';end if;select id into cached from public.creative_assets where workspace_id=p.workspace_id and cache_key=p_input->>'cacheKey'and status='draft'limit 1;insert into public.creative_campaigns(organization_id,workspace_id,project_id,name,status,brief,payload,created_by,updated_by)values(p.organization_id,p.workspace_id,p.id,left((p_input->>'format')||' · '||p.name,160),'draft',jsonb_build_object('campaignType','Custom','audiences','[]'::jsonb,'platforms',jsonb_build_array(p_input->>'format'),'language','English','objective',p_input->>'prompt'),jsonb_build_object('projectName',p.name,'developer',p.developer,'generation','ai-image'),auth.uid(),auth.uid())returning id into c;insert into public.creative_generation_jobs(organization_id,workspace_id,project_id,campaign_id,prompt,format,layout_style,cache_key,status,progress,asset_id,created_by,completed_at)values(p.organization_id,p.workspace_id,p.id,c,trim(p_input->>'prompt'),left(p_input->>'format',100),p_input->>'layoutStyle',p_input->>'cacheKey',case when cached is null then'queued'else'completed'end,case when cached is null then 0 else 100 end,cached,auth.uid(),case when cached is null then null else now()end)returning id into j;insert into public.creative_timeline(organization_id,workspace_id,campaign_id,event_type,prompt_reference,ai_employee,project_id,metadata,actor_id)values(p.organization_id,p.workspace_id,c,case when cached is null then'generation.queued'else'generation.cache_hit'end,'Stored privately on generation job','Creative AI',p.id,jsonb_build_object('job_id',j,'layout',p_input->>'layoutStyle','format',p_input->>'format','draft_only',true),auth.uid());return j;end$$;
create or replace function public.claim_creative_generation(p_job_id uuid)returns jsonb language plpgsql security definer set search_path=public as $$declare j public.creative_generation_jobs%rowtype;begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;select*into j from public.creative_generation_jobs where id=p_job_id and(status='queued'or(status='failed'and attempts<max_attempts))for update skip locked;if not found then return null;end if;update public.creative_generation_jobs set status='processing',progress=10,attempts=attempts+1,claimed_at=now(),updated_at=now()where id=j.id;return to_jsonb(j)||jsonb_build_object('status','processing','attempts',j.attempts+1);end$$;
create or replace function public.complete_creative_generation(p_job_id uuid,p_success boolean,p_storage_path text,p_mime_type text,p_model text,p_latency_ms integer,p_diagnostic text,p_reasoning_summary text)returns void language plpgsql security definer set search_path=public as $$declare j public.creative_generation_jobs%rowtype;a uuid;begin if current_setting('role',true)<>'service_role'then raise exception'service role required';end if;select*into j from public.creative_generation_jobs where id=p_job_id for update;if not found then raise exception'generation job unavailable';end if;if p_success then insert into public.creative_assets(organization_id,workspace_id,campaign_id,project_id,name,category,format,platform,language,status,prompt,ai_employee,edits,exports,publishing_history,storyboard,generated_at,created_by,version,storage_path,mime_type,model,reasoning_summary,cache_key)values(j.organization_id,j.workspace_id,j.campaign_id,j.project_id,j.format||' · AI draft','image',j.format,j.format,'English','draft',j.prompt,'Creative AI','{}','{}','{}',null,now(),j.created_by,1,p_storage_path,p_mime_type,p_model,p_reasoning_summary,j.cache_key)returning id into a;insert into public.creative_editor_documents(asset_id,organization_id,workspace_id,width,height,elements,updated_by)values(a,j.organization_id,j.workspace_id,case when j.format~*'banner|linkedin|facebook'then 1536 else 1024 end,case when j.format~*'story|poster|flyer|brochure|whatsapp'then 1536 else 1024 end,jsonb_build_array(jsonb_build_object('id','background','type','image','x',0,'y',0,'width',1024,'height',1024,'content',p_storage_path,'style','{}'::jsonb),jsonb_build_object('id','headline','type','text','x',80,'y',90,'width',700,'height',150,'content','Edit campaign headline','style',jsonb_build_object('fontSize',64,'fontWeight',700))),j.created_by);update public.creative_generation_jobs set status='completed',progress=100,asset_id=a,diagnostic=null,completed_at=now(),updated_at=now()where id=j.id;insert into public.creative_timeline(organization_id,workspace_id,campaign_id,asset_id,event_type,prompt_reference,ai_employee,project_id,metadata,actor_id)values(j.organization_id,j.workspace_id,j.campaign_id,a,'generation.completed','Private job prompt','Creative AI',j.project_id,jsonb_build_object('job_id',j.id,'model',p_model,'latency_ms',p_latency_ms,'status','draft','publishing_disabled',true),j.created_by);else update public.creative_generation_jobs set status=case when attempts<max_attempts then'queued'else'failed'end,progress=0,diagnostic=left(coalesce(p_diagnostic,'provider_exception'),120),updated_at=now()where id=j.id;insert into public.creative_timeline(organization_id,workspace_id,campaign_id,event_type,ai_employee,project_id,metadata,actor_id)values(j.organization_id,j.workspace_id,j.campaign_id,'generation.failed','Creative AI',j.project_id,jsonb_build_object('job_id',j.id,'diagnostic',left(coalesce(p_diagnostic,'provider_exception'),120),'retry_available',j.attempts<j.max_attempts),j.created_by);end if;end$$;
create or replace function public.autosave_creative_editor(p_asset_id uuid,p_expected_revision integer,p_elements jsonb)returns integer language plpgsql security definer set search_path=public as $$declare d public.creative_editor_documents%rowtype;next_revision integer;begin select*into d from public.creative_editor_documents where asset_id=p_asset_id for update;if not found or not public.creative_studio_manage(d.workspace_id)then raise exception'insufficient editor permission';end if;if d.revision<>p_expected_revision then raise exception'editor document changed';end if;if jsonb_typeof(p_elements)<>'array'or jsonb_array_length(p_elements)>250 then raise exception'invalid editor document';end if;next_revision=d.revision+1;update public.creative_editor_documents set elements=p_elements,revision=next_revision,updated_by=auth.uid(),updated_at=now()where asset_id=p_asset_id;insert into public.creative_timeline(organization_id,workspace_id,asset_id,event_type,metadata,actor_id)values(d.organization_id,d.workspace_id,d.asset_id,'editor.autosaved',jsonb_build_object('revision',next_revision,'element_count',jsonb_array_length(p_elements)),auth.uid());return next_revision;end$$;
revoke all on function public.enqueue_creative_generation(jsonb)from public;grant execute on function public.enqueue_creative_generation(jsonb)to authenticated;revoke all on function public.claim_creative_generation(uuid)from public;grant execute on function public.claim_creative_generation(uuid)to service_role;revoke all on function public.complete_creative_generation(uuid,boolean,text,text,text,integer,text,text)from public;grant execute on function public.complete_creative_generation(uuid,boolean,text,text,text,integer,text,text)to service_role;revoke all on function public.autosave_creative_editor(uuid,integer,jsonb)from public;grant execute on function public.autosave_creative_editor(uuid,integer,jsonb)to authenticated;
